#!/usr/bin/env python3
"""Builds podcast_script_gemengepakt{,_fr,_de,_lb}.md from build/gemengepakt_src/<lang>.txt
(body turns: 'A: text' = Anna, 'T: text' = Tom, 'C: text' = Anna's closing line, followed by the standard outro)
+ the standard Biergerpakt intro/outro taken from the kjt scripts. Edit the .txt files and re-run; do not edit the .md."""
KEY = "gemengepakt"
HEAD = {
 "en": ('# Podcast Script — "Living Together in Your Commune – The Communal Pact"', "**Part of the Biergerpakt programme**", "**Hosts:** Anna (woman) and Tom (man)", "**Length:** about {MIN} minutes — spoken slowly, in simple English"),
 "fr": ("# Script du podcast — « Vivre ensemble dans votre commune – Le pacte communal »", "**Dans le cadre du programme Biergerpakt**", "**Animateurs :** Anna (femme) et Tom (homme)", "**Durée :** environ {MIN} minutes — parlé lentement, dans un français simple"),
 "de": ("# Podcast-Skript — „Zusammenleben in Ihrer Gemeinde – Der Gemeindepakt“", "**Teil des Biergerpakt-Programms**", "**Moderation:** Anna (Frau) und Tom (Mann)", "**Länge:** etwa {MIN} Minuten — langsam gesprochen, in einfachem Deutsch"),
 "lb": ("# Podcast-Skript — „Zesummeliewen an Ärer Gemeng – De Gemengepakt“", "**Deel vum Biergerpakt-Programm**", "**Moderatioun:** Anna (Fra) an Tom (Mann)", "**Längt:** ongeféier {MIN} Minutten — lues geschwat, an engem einfache Lëtzebuergesch"),
}
MIN = {"en": 11, "fr": 10, "de": 12, "lb": 11}   # EN 10:38, FR 10:04, DE 11:45 (28 Nov 2026)
OUTRO_START = {"en": "This podcast is part of the Biergerpakt, a programme", "fr": "Ce podcast fait partie du Biergerpakt, un programme",
               "de": "Dieser Podcast ist Teil des Biergerpakt, ein Programm", "lb": "Dëse Podcast ass Deel vum Biergerpakt, engem Programm"}
SOURCES = {
 "en": "*Sources (official only, consulted on 28 November 2026): gemengen.zesummeliewen.lu, the ministry's site on living together in the communes (FR/EN/DE) — home page, \"Gemengepakt vum Zesummeliewen\" (signed by a commune or a group of communes, the SYVICOL and the Ministry of Family Affairs, Solidarity, Living Together and Reception of Refugees; access to information, participation of everyone living or working in the commune, fight against racism and all forms of discrimination; thematic cycles in five steps; builds on the pilot project \"Pakt vum Zesummeliewen\" 2021–2023; application form), \"Committee on living together\" (missions; election of the commune's representatives to the Higher Council for Intercultural Living Together), \"Forum fir d'Zesummeliewen an eise Gemengen\" (formerly GRESIL; once a year nationally, four times a year regionally; ministry with ASTI's Agence Interculturelle, supported by CEFIS and SYVICOL), \"Best practices\" (five themes), interactive map of communes. Law of 23 August 2023 on intercultural living together (Mémorial A n° 545), Art. 1 (definition), 2 (four instruments), 6 (communal pact: at most six years; staged timetable and indicators; encourages joining the Biergerpakt; evaluation six months before the end; steering committee of at least five members; ministry advisers; coordinator, internal or external, subsidy; application by a commune or a group of communes; label \"commune du vivre-ensemble interculturel\"; annual subsidies, incl. an amount per Biergerpakt member living or working in the commune), 7–8 (Higher Council), 9–10 (communal committee: in every commune within six months of the communal elections; for everyone living or working in the commune; members appointed by the communal council; at least one councillor). Ministry FAQ on the law (22 December 2023): committee replaces the former integration committee, recommended name, cross-border workers eligible, call for candidates; free advice for communes with a pact; renewal by a new application. gouvernement.lu press releases of the ministry on the signing ceremonies (2024–2026: five steps, ASTI and CEFIS, advisers, Biergerguide in five languages with the parts \"Je découvre ma commune\" and \"Je m'engage dans ma commune\", more than fifty signatory communes since 2024). Durable wording only: no subsidy amounts, no number of advisers, no exact count of communes, no names. Voting is explained in the episode I Can Vote; the SYVICOL has its own episode. General information only; only the legal texts are binding. Accurate as of November 2026.*",
 "fr": "*Sources (officielles uniquement, consultées le 28 novembre 2026) : gemengen.zesummeliewen.lu, le site du ministère sur le vivre-ensemble dans les communes — accueil, « Gemengepakt vum Zesummeliewen » (signé par une commune ou un groupement de communes, le SYVICOL et le ministère de la Famille, des Solidarités, du Vivre ensemble et de l'Accueil ; accès à l'information, participation de toutes les personnes qui vivent ou travaillent dans la commune, lutte contre le racisme et toutes les formes de discrimination ; cycles thématiques en cinq étapes ; s'appuie sur le projet pilote « Pakt vum Zesummeliewen » 2021-2023), « Commission du vivre-ensemble » (missions ; élection des représentants au Conseil supérieur du vivre-ensemble interculturel), « Forum fir d'Zesummeliewen an eise Gemengen » (ancien GRESIL ; une fois par an au niveau national, quatre fois par an au niveau régional ; ministère avec l'Agence interculturelle de l'ASTI, avec le soutien du CEFIS et du SYVICOL), « Bonnes pratiques » (cinq thèmes), carte interactive des communes. Loi du 23 août 2023 relative au vivre-ensemble interculturel (Mémorial A n° 545), art. 1er, 2, 6 (pacte communal : six ans au maximum ; comité de pilotage d'au moins cinq membres ; conseillers au vivre-ensemble interculturel ; coordinateur ; évaluation six mois avant la fin ; label « commune du vivre-ensemble interculturel » ; subventions, dont un montant par membre du pacte citoyen), 7-8 (Conseil supérieur), 9-10 (commission communale). FAQ du ministère sur la loi (22 décembre 2023). Communiqués du ministère sur gouvernement.lu (cérémonies de signature 2024-2026 ; Biergerguide en cinq langues, « Je découvre ma commune » et « Je m'engage dans ma commune » ; plus de cinquante communes signataires depuis 2024). Formulations durables uniquement : pas de montants de subventions, pas de nombre exact de communes, pas de noms. Informations générales uniquement ; seuls les textes légaux font foi. Exact en novembre 2026.*",
 "de": "*Quellen (nur offizielle, abgerufen am 28. November 2026): gemengen.zesummeliewen.lu, die Website des Ministeriums zum Zusammenleben in den Gemeinden — Startseite, „Gemengepakt vum Zesummeliewen“ (unterzeichnet von einer Gemeinde oder einem Gemeindeverbund, dem SYVICOL und dem Ministerium für Familie, Solidarität, Zusammenleben und Unterbringung von Flüchtlingen; Zugang zu Informationen, Beteiligung aller, die in der Gemeinde leben oder arbeiten, Kampf gegen Rassismus und jede Form von Diskriminierung; thematische Zyklen in fünf Schritten; Pilotprojekt „Pakt vum Zesummeliewen“ 2021–2023), „Kommission für das Zusammenleben“, „Forum fir d'Zesummeliewen an eise Gemengen“ (früher GRESIL), „Gute Beispiele“ (fünf Themen), Karte der Gemeinden. Gesetz vom 23. August 2023 über das interkulturelle Zusammenleben (Mémorial A Nr. 545), Art. 1, 2, 6 (Gemeindepakt: höchstens sechs Jahre; Lenkungsausschuss mit mindestens fünf Mitgliedern; Berater; Koordinator; Bewertung sechs Monate vor dem Ende; Label; Zuschüsse, darunter ein Betrag pro Mitglied des Biergerpakt), 7–8 (Oberster Rat), 9–10 (Gemeindekommission). FAQ des Ministeriums zum Gesetz (22. Dezember 2023). Pressemitteilungen des Ministeriums auf gouvernement.lu (Unterzeichnungen 2024–2026; Biergerguide in fünf Sprachen; mehr als fünfzig Gemeinden seit 2024). Nur dauerhafte Angaben: keine Zuschussbeträge, keine genaue Zahl der Gemeinden, keine Namen. Nur allgemeine Informationen; verbindlich sind allein die Gesetzestexte. Stand: November 2026.*",
 "lb": "*Quellen: gemengen.zesummeliewen.lu (Gemengepakt, Kommissioun fir d'Zesummeliewen, Forum, gutt Beispiller, Kaart), Gesetz vum 23. August 2023 iwwer dat interkulturellt Zesummeliewen (Art. 1, 2, 6–10), FAQ vum Ministère (22. Dezember 2023), Pressecommuniquéen op gouvernement.lu (2024–2026), consultéiert de 28. November 2026. Keng Montanten, keng genee Zuel vu Gemengen. Nëmmen allgemeng Informatiounen; nëmmen d'Gesetzestexter sinn bindend. Stand: November 2026.*",
}
def turns(path):
    return [l.rstrip("\n") for l in open(path, encoding="utf-8") if l.startswith("**ANNA") or l.startswith("**TOM")]
for lang in ("en", "fr", "de", "lb"):
    sfx = "" if lang == "en" else "_" + lang
    ref = turns(f"podcast_script_kjt{sfx}.md")
    intro, closing, last2 = ref[:3], ref[-3], ref[-2:]
    outro = closing[closing.index(OUTRO_START[lang]):]
    body = []
    for l in open(f"build/gemengepakt_src/{lang}.txt", encoding="utf-8"):
        l = l.strip()
        if not l: continue
        who, txt = l.split(": ", 1)
        assert who in ("A", "T", "C"), l[:30]
        if who == "C": txt += " " + outro
        body.append(f"**{'TOM' if who == 'T' else 'ANNA'}:** {txt}")
    assert len(body) == 50, (lang, len(body))
    seq = [x[2] for x in intro + body + last2]
    assert all(a != b for a, b in zip(seq, seq[1:])), (lang, "same speaker twice")
    head = [h.replace("{MIN}", str(MIN[lang])) for h in HEAD[lang]]
    out = "\n".join([head[0], "", *head[1:], "", "---", "", *intro, *body, *last2, "", "---", "", SOURCES[lang], ""])
    open(f"podcast_script_{KEY}{sfx}.md", "w", encoding="utf-8").write(out)
    t = turns(f"podcast_script_{KEY}{sfx}.md")
    print(lang, len(t), "turns;", "..." in out or "…" in out, "ellipsis;", sum(len(x.split(":** ",1)[1]) for x in t), "chars")
